"""Dependency-free Ingress UI using the Agent Control Plane visual language."""

ADMIN_CSS = r"""
:root{color-scheme:light;--bg:#f3f6f9;--surface:#fff;--surface2:#edf3f7;--text:#17243a;--muted:#687b90;--line:#d8e2eb;--cyan:#058caf;--cyan-soft:#dff5fa;--good:#16845b;--shadow:0 5px 22px #1e3a5f12}
html[data-theme=dark]{color-scheme:dark;--bg:#0d1420;--surface:#172235;--surface2:#202c41;--text:#e7edf5;--muted:#a4b2c6;--line:#30415d;--cyan:#52c9e6;--cyan-soft:#173b4a;--good:#50c895;--shadow:none}
*{box-sizing:border-box}[hidden]{display:none!important}body{font:15px system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:var(--bg);color:var(--text);margin:0}.app{max-width:1840px;margin:auto;padding:22px clamp(18px,2.8vw,48px) 40px}.site-header{margin-bottom:28px}.header-main{display:flex;align-items:center;gap:20px;min-height:58px}.brand{display:flex;align-items:center;gap:11px;color:var(--cyan);text-decoration:none;font-size:24px;font-weight:800;letter-spacing:-.02em}.brand img{width:46px;height:46px;object-fit:contain;filter:drop-shadow(0 4px 8px #102a4330)}.brand b{font-size:13px;color:var(--muted);font-weight:650;white-space:nowrap}.header-actions{display:flex;gap:8px;margin-left:auto}.switch{color:var(--text);padding:9px 12px;border-radius:7px;border:1px solid var(--line);background:var(--surface);font:inherit;cursor:pointer}.nav-scroll{margin-top:12px;overflow-x:auto}.nav{display:flex;gap:5px;width:max-content;min-width:100%}.nav a{color:var(--text);text-decoration:none;padding:9px 12px;border-radius:7px}.nav a.active{background:var(--cyan-soft);color:var(--cyan);font-weight:700}.view{display:none}.view.active{display:block}.hero{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:24px;align-items:center;margin:4px 0 20px}.hero h1,.pagehead h1{font-size:29px;margin:0 0 5px;letter-spacing:-.025em}.hero p,.pagehead p{margin:0;color:var(--muted)}.health{display:flex;align-items:center;gap:8px;color:var(--good);font-weight:700;background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:11px 14px;box-shadow:var(--shadow)}.health i{width:9px;height:9px;border-radius:50%;background:currentColor;box-shadow:0 0 0 4px color-mix(in srgb,currentColor 15%,transparent)}.metrics{display:grid;grid-template-columns:repeat(3,minmax(150px,1fr));gap:12px}.card,.metric{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:18px;box-shadow:var(--shadow)}.metric{position:relative;overflow:hidden}.metric:before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--cyan)}.metric strong{display:block;font-size:25px;line-height:1.2}.metric span,.metric small{display:block;color:var(--muted);margin-top:5px}.notice{margin-top:16px}.notice h2{font-size:19px;margin:0 0 7px}.notice p{margin:0;color:var(--muted);line-height:1.5}.pagehead{margin:4px 0 20px}.tablewrap{overflow:auto;border:1px solid var(--line);border-radius:10px}table{width:100%;border-collapse:collapse;white-space:nowrap}th,td{text-align:left;padding:11px 12px;border-bottom:1px solid var(--line)}th{font-size:12px;color:var(--muted);background:var(--surface2)}tr:last-child td{border:0}.state{display:inline-block;padding:3px 8px;border-radius:999px;background:var(--cyan-soft);color:var(--good);font-size:12px}.empty{text-align:center;padding:42px;color:var(--muted)}.pager{display:flex;justify-content:flex-end;align-items:center;gap:10px;margin-top:14px}.pager button{color:var(--text);background:var(--surface2);border:1px solid var(--line);border-radius:7px;padding:8px 11px;cursor:pointer}.pager button:disabled{opacity:.5;cursor:not-allowed}.technical{font:12px ui-monospace,SFMono-Regular,Consolas,monospace;color:var(--muted)}
@media(max-width:850px){.app{padding:16px}.nav-scroll{margin-inline:-16px;padding-inline:16px}.hero{grid-template-columns:1fr}.health{justify-self:start}.metrics{grid-template-columns:1fr}}@media(max-width:560px){.brand{font-size:19px}.brand img{width:40px;height:40px}.header-main{align-items:flex-start}.header-actions{flex-direction:column}.hero h1{font-size:25px}}
.pagehead.split{display:flex;justify-content:space-between;align-items:center;gap:16px}.primary,.secondary,.danger{border:0;border-radius:7px;padding:9px 12px;font:inherit;font-weight:700;cursor:pointer}.primary{background:var(--cyan);color:#fff}.secondary{background:var(--surface2);color:var(--text);border:1px solid var(--line)}.danger{background:transparent;color:#c43f55;border:1px solid #c43f5555}.actions{display:flex;gap:6px}.model-form{display:grid;grid-template-columns:1fr 1fr;gap:12px}.model-form label{font-weight:650}.model-form input,.model-form select{width:100%;padding:9px;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:7px}.model-form .wide{grid-column:1/-1}.warning{padding:10px;background:#fff5df;color:#76520f;border-radius:7px}.dialog{position:fixed;inset:0;background:#07132180;display:grid;place-items:center;padding:18px;z-index:20}.dialog>.card{width:min(680px,100%);max-height:calc(100vh - 36px);overflow:auto}.dialog-head{display:flex;justify-content:space-between}.message{color:#c43f55}.state.unavailable,.state.incompatible{color:#c43f55}.state.unverified{color:#9a6800}@media(max-width:650px){.model-form{grid-template-columns:1fr}.model-form .wide{grid-column:auto}.pagehead.split{align-items:flex-start;flex-direction:column}}
.oauth-account{display:flex;align-items:center;gap:14px;margin-bottom:16px}.oauth-account>div:first-child{flex:1}.oauth-account h2{font-size:18px;margin:0 0 5px}.oauth-account p{margin:0;color:var(--muted)}.device-code{font:700 18px ui-monospace,SFMono-Regular,Consolas,monospace;letter-spacing:.06em}.oauth-account a{color:var(--cyan)}@media(max-width:650px){.oauth-account{align-items:flex-start;flex-direction:column}}
"""

